import java.util.function.IntFunction;

public final class PluginBoundary {
    public static void deliver(int serverSelectedCode, Plugin plugin) {
        plugin.accept(OpaqueCode.of(serverSelectedCode), OpaqueCode::of);
    }

    public interface Plugin {
        void accept(Object serverObject, IntFunction<Object> candidateFactory);
    }
}

